  KEY `os_cash_payouts_kyo_shin_batch_id_index` (`kyo_shin_batch_id`),
  KEY `os_cash_payouts_branch_id_index` (`branch_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
